const panelDesign = {"html":"<main class=\"panel-navigator\"><header><div><span class=\"eyebrow\">Page explorer</span><h1 id=\"title\">Outline &amp; links</h1></div><button id=\"refresh\" class=\"icon-button\" aria-label=\"Refresh page map\" title=\"Refresh page map\"><svg viewBox=\"0 0 24 24\"><path d=\"M20 7v5h-5M20 12a8 8 0 1 0-2 5\"/></svg></button></header>\n<div class=\"stats\"><div><strong id=\"sections\">0</strong><small>sections</small></div><div><strong id=\"link-count\">0</strong><small>links</small></div><div><strong id=\"domains\">0</strong><small>sources</small></div></div>\n<div class=\"toolbar\"><div class=\"search-field\"><svg viewBox=\"0 0 24 24\"><circle cx=\"10.5\" cy=\"10.5\" r=\"6.5\"/><path d=\"m16 16 4 4\"/></svg><input type=\"search\" id=\"search\" placeholder=\"Find a section or source\" aria-label=\"Search sections and links\"></div><div class=\"segments\"><button id=\"outline-tab\" aria-pressed=\"true\">Outline</button><button id=\"links-tab\" aria-pressed=\"false\">Links &amp; sources</button></div><select id=\"link-filter\" aria-label=\"Link filter\" hidden><option value=\"all\">All links</option><option value=\"external\">External sources</option><option value=\"internal\">This website</option></select></div>\n<p id=\"summary\" class=\"muted\"></p><div id=\"results\" class=\"list\"></div><p id=\"error\" class=\"error\" role=\"alert\"></p><details><summary>About this page map</summary><p class=\"muted\">Shows visible headings and links on this page. Refresh after loading more content. Nothing is uploaded and the page stays unchanged.</p></details></main>\n","css":"*{box-sizing:border-box}body{margin:0}main{padding:16px;max-width:900px;margin:auto}header{display:flex;align-items:start;justify-content:space-between;gap:10px;margin-bottom:16px}h1{font-size:20px;line-height:1.25;letter-spacing:-.4px;margin:4px 0 8px}h2{font-size:14px;margin:0 0 10px}p{margin:6px 0;line-height:1.6}.eyebrow{font-size:10px;letter-spacing:1.6px;text-transform:uppercase;opacity:.6}.muted,small{opacity:.65;font-size:12px;line-height:1.5}.card{padding:14px;border-radius:14px;background:color-mix(in srgb,CanvasText 5%,Canvas);margin:12px 0}.row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.row>*{min-width:0}.grow{flex:1}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(145px,100%),1fr));gap:10px}button,input,select{font:inherit}button{border:0;border-radius:9px;padding:8px 11px;background:color-mix(in srgb,CanvasText 8%,Canvas);color:inherit;cursor:pointer}button:hover{background:color-mix(in srgb,CanvasText 13%,Canvas)}button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--kudium-primary);outline-offset:3px}.primary{background:var(--kudium-primary);color:var(--kudium-primary-contrast);font-weight:650}button:disabled{opacity:.4;cursor:default}input,select{min-width:0;width:100%;padding:9px 10px;border:0;border-radius:9px;background:color-mix(in srgb,CanvasText 7%,Canvas);color:inherit}label{display:block;font-size:12px}label input,label select{margin-top:6px}a{color:inherit;text-decoration:none;overflow-wrap:anywhere}a:hover{text-decoration:underline}.list{display:grid;gap:6px}.item{width:100%;padding:11px;text-align:left;background:color-mix(in srgb,CanvasText 4%,Canvas);border-radius:10px}.item strong,.item small{display:block;overflow-wrap:anywhere}.item strong{font-size:12px;font-weight:550}.pill{font-size:10px;padding:5px 8px;background:color-mix(in srgb,var(--kudium-primary) 15%,Canvas);border-radius:99px;white-space:nowrap}.error{color:light-dark(#ad2828,#ff9b9b)}[hidden]{display:none!important}details summary{cursor:pointer;font-size:13px}.stats{display:flex;gap:16px;flex-wrap:wrap;margin:12px 0}.stats strong{display:block;font-size:22px}.stats small{font-size:10px}.empty{padding:18px;text-align:center;opacity:.6;font-size:13px}#error:empty{display:none}.toolbar{position:sticky;top:0;background:Canvas;padding:10px 0;z-index:1}code{font-family:ui-monospace,monospace;font-size:11px;overflow-wrap:anywhere}@media(max-width:340px){main{padding:12px}h1{font-size:18px}.card{padding:11px}}\n\nheader>button,header>.pill{flex-shrink:0}header>div{min-width:0}.row>button,header>button{white-space:nowrap}.item{white-space:normal}\n.item .grow{white-space:normal;overflow-wrap:anywhere}\n\n.primary:hover{background:var(--kudium-primary);filter:brightness(1.08)}\n\n.panel-navigator{padding:20px 16px;max-width:760px;font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}.panel-navigator header{margin-bottom:18px;align-items:center}.panel-navigator .eyebrow{font-size:11px;letter-spacing:0;text-transform:none;opacity:.5}.panel-navigator h1{font-size:19px;font-weight:650;line-height:1.35;letter-spacing:-.4px;margin:8px 0}.panel-navigator .muted{font-size:11px}.panel-navigator #branch{overflow-wrap:anywhere;font-size:10px}.panel-navigator svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}.panel-navigator .icon-button{width:32px;height:32px;flex-shrink:0;padding:7px;display:grid;place-items:center;background:transparent;border-radius:50%;opacity:.6}.panel-navigator .icon-button:hover{background:color-mix(in srgb,CanvasText 7%,Canvas);opacity:1}.panel-navigator .stats{gap:14px;margin:14px 0 18px}.panel-navigator .stats>div{display:flex;gap:5px;align-items:baseline}.panel-navigator .stats strong{font-size:13px;font-weight:650}.panel-navigator .stats small{font-size:10px;text-transform:none}.panel-navigator .toolbar{padding:8px 0 12px;background:Canvas;z-index:1}.search-field{position:relative}.search-field>svg{position:absolute;left:10px;top:11px;width:15px;height:15px;opacity:.45;pointer-events:none}.panel-navigator input[type=search]{padding:10px 12px 10px 33px;font-size:12px;background:color-mix(in srgb,CanvasText 5%,Canvas);border-radius:10px}.panel-navigator select{font-size:11px;padding:8px;background:color-mix(in srgb,CanvasText 5%,Canvas);border-radius:8px}.filter-row{display:flex;align-items:center;gap:10px;margin-top:10px}.filter-row select{width:auto;max-width:60%;flex:1}.filter-row a{margin-left:auto;font-size:10px;white-space:nowrap;display:flex;gap:3px;align-items:center}.filter-row a svg{width:13px;height:13px}.panel-navigator .list{gap:2px}.panel-navigator .item{background:transparent;padding:11px 8px;border-radius:9px;display:flex;align-items:center;gap:8px}.panel-navigator .item:hover{background:color-mix(in srgb,CanvasText 4%,Canvas);text-decoration:none}.panel-navigator .item strong{font-size:12px;font-weight:500;line-height:1.5}.panel-navigator .item small{font-size:10px;margin-top:3px;line-height:1.45}.panel-navigator .file-icon{opacity:.35;width:16px;height:16px;align-self:flex-start;margin-top:3px}.panel-navigator .check-button{background:transparent;padding:6px;width:30px;height:30px;flex-shrink:0;border-radius:50%;opacity:.5;display:grid;place-items:center}.panel-navigator .check-button[aria-pressed=true]{background:color-mix(in srgb,var(--kudium-primary) 14%,Canvas);color:var(--kudium-primary);opacity:1}.panel-navigator .check-button:hover{opacity:1}.panel-navigator .segments{display:flex;gap:3px;padding:3px;border-radius:9px;background:color-mix(in srgb,CanvasText 5%,Canvas);margin-top:10px}.panel-navigator .segments button{flex:1;background:transparent;font-size:11px;padding:7px 8px;border-radius:7px;opacity:.6;white-space:nowrap}.panel-navigator .segments button[aria-pressed=true]{background:color-mix(in srgb,CanvasText 10%,Canvas);color:inherit;opacity:1;filter:none;font-weight:550}.panel-navigator #link-filter{width:100%;margin-top:8px}.panel-navigator #notice,.panel-navigator #summary{font-size:10px;margin:2px 0 9px;opacity:.5}.panel-navigator .source-arrow{opacity:.35;width:14px;height:14px;margin-left:auto}.panel-navigator details{margin-top:12px}.panel-navigator summary{font-size:11px;cursor:pointer;opacity:.65;padding:8px 0}.panel-navigator details p{font-size:11px;line-height:1.65}.panel-navigator .local-note{font-size:10px;opacity:.45;margin:18px 0 0}.panel-navigator #description{white-space:pre-wrap}.panel-navigator #threads .item{display:block;font-size:11px;line-height:1.6}@media(max-width:340px){.panel-navigator{padding:16px 12px}.panel-navigator h1{font-size:18px}.panel-navigator .stats{gap:10px}}\n","script":"let explorerData, mode='outline';const el=id=>document.getElementById(id);\nfunction render(){if(!explorerData)return;const query=el('search').value.toLowerCase(),filter=el('link-filter').value;el('results').replaceChildren();\n  const entries=mode==='outline'?explorerData.headings.filter(item=>item.text.toLowerCase().includes(query)):explorerData.links.filter(item=>(item.label+' '+item.domain+' '+item.url).toLowerCase().includes(query)&&(filter!=='external'||item.external)&&(filter!=='internal'||!item.external));\n  for(const item of entries){const row=document.createElement(mode==='outline'?'button':'a');row.className='item';const title=document.createElement('strong');title.textContent=mode==='outline'?item.text:item.label;const content=document.createElement('div');content.className='grow';content.append(title);row.append(content);if(mode==='outline'){row.style.paddingLeft=(11+Math.min(3,item.level-1)*12)+'px';row.onclick=async()=>{try{await kudiumHookPanel.invoke('explorer-jump',{index:item.index});}catch(error){el('error').textContent=error.message;}};}else{row.href=item.url;const detail=document.createElement('small');detail.textContent=item.domain+(item.external?' · external source':' · this website');content.append(detail);const arrow=document.createElementNS('http://www.w3.org/2000/svg','svg');arrow.setAttribute('viewBox','0 0 24 24');arrow.classList.add('source-arrow');arrow.setAttribute('aria-hidden','true');arrow.innerHTML='<path d=\"M7 17 17 7M7 7h10v10\"/>';row.append(arrow);}el('results').append(row);}\n  el('summary').textContent=entries.length+' '+(mode==='outline'?'sections':'links')+' shown';if(!entries.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='No '+(mode==='outline'?'headings':'links')+' match. Try another search or Refresh.';el('results').append(empty);}}\nfor(const [id,next] of [['outline-tab','outline'],['links-tab','links']])el(id).onclick=()=>{mode=next;el('link-filter').hidden=mode==='outline';for(const [button,value] of [['outline-tab','outline'],['links-tab','links']]){el(button).classList.toggle('primary',mode===value);el(button).setAttribute('aria-pressed',String(mode===value));}render();};\nel('search').oninput=render;el('link-filter').onchange=render;el('refresh').onclick=async()=>{el('refresh').disabled=true;try{await kudiumHookPanel.invoke('explorer-refresh');el('error').textContent='';}catch(error){el('error').textContent=error.message;}finally{el('refresh').disabled=false;}};\nkudiumHookPanel.onUpdate(output=>{explorerData=output.content.data;el('title').textContent=explorerData.title;el('sections').textContent=explorerData.headings.length;el('link-count').textContent=explorerData.links.length;el('domains').textContent=new Set(explorerData.links.filter(item=>item.external).map(item=>item.domain)).size;render();});\n"};
let explorerNodes = [];
const safeLink = raw => { try {const target=new URL(raw,location.href);return /^https?:$/.test(target.protocol)&&!target.username&&!target.password&&target.href.length<=2048?target.href:null;}catch{return null;} };
const scanPage = () => {
  const pageRoot = document.querySelector('article,main,[role="main"]') || document.body;
  explorerNodes = [...pageRoot.querySelectorAll('h1,h2,h3,h4')].filter(node=>node.getClientRects().length&&node.textContent.trim()).slice(0,120);
  const links = new Map(); let linkBudget = 0;
  for(const anchor of pageRoot.querySelectorAll('a[href]')) {
    if(!anchor.getClientRects().length||anchor.closest('nav,footer,aside'))continue;
    const target=safeLink(anchor.getAttribute('href'));if(!target||links.has(target))continue;
    const parsed=new URL(target);const entry={url:target,label:(anchor.textContent.trim()||parsed.hostname).slice(0,180),domain:parsed.hostname,external:parsed.origin!==location.origin};
    const size=JSON.stringify(entry).length;if(linkBudget+size>35000)break;linkBudget+=size;links.set(target,entry);
    if(links.size>=180)break;
  }
  return {title:document.title.slice(0,200),url:location.href.slice(0,2048),headings:explorerNodes.map((node,index)=>({index,text:node.textContent.trim().slice(0,240),level:Number(node.tagName[1])})),links:[...links.values()]};
};
const explorerActions=[{id:'explorer-refresh',label:'Refresh'},{id:'explorer-jump',label:'Jump to section'}];
context.panel.onAction('explorer-refresh',async()=>{await context.panel.update({id:'explorer',title:'Page outline & links',content:{type:'html',...panelDesign,data:scanPage()},actions:explorerActions});return {refreshed:true};});
context.panel.onAction('explorer-jump',async payload=>{if(!Number.isInteger(payload?.index)||!explorerNodes[payload.index])throw new Error('Refresh the outline first.');explorerNodes[payload.index].scrollIntoView({behavior:'auto',block:'start'});return {jumped:true};});
await context.panel.show({id:'explorer',title:'Page outline & links',reveal:false,content:{type:'html',...panelDesign,data:scanPage()},actions:explorerActions});
